select is((select count(*)::int from public.products p where p.stock_qty <> coalesce((select sum(m.qty_delta) from public.stock_movements m where m.product_id = p.id), 0)), 0, 'invariant: stock equals the sum of movements');
select is((select count(*)::int from public.sales s where s.total <> (select sum(round(i.qty * i.unit_price, 2)) from public.sale_items i where i.sale_id = s.id)), 0, 'invariant: sale total equals its items');
select is((select count(*)::int from (select customer_id, sum(amount) as bal from public.customer_ledger group by customer_id) l join public.customer_balances b on b.customer_id = l.customer_id where b.balance <> l.bal), 0, 'invariant: customer balance equals the ledger sum');
